package app.cryptoresearch.mobile;
import java.util.*;import java.time.*;
/** Independent mobile spot EMA9/21 engine. Paper fills only; no transport. */
public final class StrategyCore {
 public static final class Bar {public long t;public double o,h,l,c,v;public Bar(long t,double o,double h,double l,double c,double v){this.t=t;this.o=o;this.h=h;this.l=l;this.c=c;this.v=v;}}
 public static List<Bar> csv(String raw){String[] lines=raw.replace("\uFEFF","").replace("\r","").split("\n");if(lines.length<3||lines.length>50001)throw new IllegalArgumentException("CSV 2~50000봉 필요");String[] head=lines[0].split(",",-1);Map<String,Integer> idx=new HashMap<>();for(int i=0;i<head.length;i++)idx.put(head[i].trim().replace("\"","").toLowerCase(Locale.ROOT),i);for(String k:new String[]{"timestamp","open","high","low","close","volume"})if(!idx.containsKey(k))throw new IllegalArgumentException("timestamp,open,high,low,close,volume 필요");List<Bar> out=new ArrayList<>();long prev=Long.MIN_VALUE;for(int n=1;n<lines.length;n++){if(lines[n].isBlank())continue;String[] fields=lines[n].split(",",-1);try{long t=OffsetDateTime.parse(fields[idx.get("timestamp")].trim().replace("\"","")).toInstant().toEpochMilli();double[] x=new double[5];int j=0;for(String k:new String[]{"open","high","low","close","volume"}){x[j]=Double.parseDouble(fields[idx.get(k)].trim().replace("\"",""));if(!Double.isFinite(x[j]))throw new Exception();j++;}if(t<=prev||Math.min(Math.min(x[0],x[1]),Math.min(x[2],x[3]))<=0||x[4]<0||x[2]>Math.min(x[0],x[3])||x[1]<Math.max(x[0],x[3])||x[1]<x[2])throw new Exception();prev=t;out.add(new Bar(t,x[0],x[1],x[2],x[3],x[4]));}catch(Exception e){throw new IllegalArgumentException("CSV "+(n+1)+"행: UTC offset/순서/OHLCV 오류");}}if(out.size()<2)throw new IllegalArgumentException("CSV 봉 부족");return out;}
 public static final class EquityPoint {public final long t;public final double equity;EquityPoint(long t,double e){this.t=t;equity=e;}}
 public static final class Fill {public final long t;public final String side;public final double price,quantity,fee;Fill(long t,String s,double p,double q,double f){this.t=t;side=s;price=p;quantity=q;fee=f;}}
 public final ArrayList<EquityPoint> curve=new ArrayList<>();public final ArrayList<Fill> fillRecords=new ArrayList<>();public int curveLimit=50000,wins;public double totalFees,grossWins,grossLosses;public String priceCurrency="INPUT_PRICE_CURRENCY";
 public void recordCurve(long t){EquityPoint point=new EquityPoint(t,equity());if(!curve.isEmpty()&&curve.get(curve.size()-1).t==t)curve.set(curve.size()-1,point);else curve.add(point);if(curve.size()>curveLimit)curve.remove(0);}
 public Double winRate(){return sells==0?null:(double)wins/sells;}public Double profitFactor(){return grossLosses==0?null:grossWins/grossLosses;}
 public final double start,fee,slip;public double cash,qty,entry,entryCost,lastPrice,ema9,ema21,peak,maxDD;public int bars,buys,sells,pending;public boolean halted;public String reason="준비";public long lastBar=Long.MIN_VALUE;public final ArrayList<String> fills=new ArrayList<>();
 public StrategyCore(double equity,double feeBps,double slipBps){if(!Double.isFinite(equity)||equity<=0||!Double.isFinite(feeBps)||feeBps<0||feeBps>100||!Double.isFinite(slipBps)||slipBps<0||slipBps>100)throw new IllegalArgumentException("자본 양수, 비용 0~100 bps");start=equity;cash=equity;peak=equity;fee=feeBps/10000;slip=slipBps/10000;}
 public double equity(){return cash+qty*lastPrice;}public void mark(double price){lastPrice=price;double e=equity();peak=Math.max(peak,e);maxDD=Math.max(maxDD,100*(peak-e)/peak);if(e<=start*.95){halted=true;reason="시작 자본 대비 5% 손실: 신규 진입 중지";}}
 void fill(long t,String side,double p,double q){fills.add(Instant.ofEpochMilli(t)+" "+side+" "+String.format(Locale.US,"%.8f @ %.4f",q,p));if(fills.size()>5000)fills.remove(0);double f=p*q*fee;totalFees+=f;fillRecords.add(new Fill(t,side,p,q,f));if(fillRecords.size()>5000)fillRecords.remove(0);}
 public void open(long t,double price){mark(price);int action=pending;pending=0;if(action<0&&qty>0)sell(t,price,"EMA 매도");else if(action>0&&qty==0&&!halted){double p=price*(1+slip),budget=cash*.1;qty=budget/(p*(1+fee));entry=p;entryCost=budget;cash-=budget;buys++;fill(t,"모의 매수",p,qty);}mark(price);}
 public void sell(long t,double price,String why){if(qty<=0)return;double p=price*(1-slip);fill(t,"모의 매도 · "+why,p,qty);double proceeds=qty*p*(1-fee),pnl=proceeds-entryCost;if(pnl>0){wins++;grossWins+=pnl;}else grossLosses-=pnl;cash+=proceeds;qty=0;sells++;mark(price);}
 public void observe(long t,double price){if(!Double.isFinite(price)||price<=0)throw new IllegalArgumentException("가격 오류");if(qty>0){if(price<=entry*.985)sell(t,price,"관측 손절");else if(price>=entry*1.03)sell(t,price,"관측 익절");}mark(price);}
 public void close(Bar b){if(b.t<=lastBar)throw new IllegalArgumentException("중복/역순 봉");lastBar=b.t;double a=ema9,z=ema21;ema9=bars==0?b.c:.2*b.c+.8*ema9;ema21=bars==0?b.c:2.0/22*b.c+20.0/22*ema21;bars++;mark(b.c);if(bars>=30){if(ema9>ema21&&a<=z&&qty==0&&!halted)pending=1;else if(ema9<ema21&&a>=z&&qty>0)pending=-1;}recordCurve(b.t);reason=halted?reason:"EMA9/21 · "+bars+"봉 · 다음 관측 가격 체결 대기";}
 public void process(Bar b){open(b.t,b.o);if(qty>0){if(b.o<=entry*.985)sell(b.t,b.o,"갭 손절");else if(b.l<=entry*.985)sell(b.t,entry*.985,"손절 우선");else if(b.h>=entry*1.03)sell(b.t,Math.max(b.o,entry*1.03),"익절");}close(b);}
 public static List<Bar> syntheticRows(){List<Bar> rows=new ArrayList<>();for(int i=0;i<32;i++)rows.add(new Bar(1767225600000L+i*60000,i==31?110:100,i>=30?110:100,i==31?110:100,i>=30?110:100,0));return rows;}
 public static StrategyCore backtest(List<Bar> rows,double equity,double fee,double slip){StrategyCore e=new StrategyCore(equity,fee,slip);for(Bar b:rows){if(Thread.currentThread().isInterrupted())throw new IllegalArgumentException("취소됨");e.process(b);}Bar last=rows.get(rows.size()-1);e.sell(last.t,last.c,"데이터 종료");e.pending=0;e.recordCurve(last.t);return e;}
 public String summary(){return String.format(Locale.KOREA,"모바일 EMA 현물 모의 전략 (기존 v1.6과 별도)\n가격 통화 기준 자본 %,.2f → 평가 %,.2f\n수익률 %+.4f%% · 최대 낙폭 %.4f%%\n매수 %d / 매도 %d · 보유 %.8f\n%s\n자본 10%% 진입 · 손절 1.5%% · 익절 3%%\n수수료 %.2f bps · 슬리피지 %.2f bps\n%s",start,equity(),(equity()/start-1)*100,maxDD,buys,sells,qty,reason,fee*10000,slip*10000,String.join("\n",fills.subList(Math.max(0,fills.size()-8),fills.size())));}
 public byte[] report(){try{org.json.JSONArray points=new org.json.JSONArray(),records=new org.json.JSONArray();for(EquityPoint p:curve)points.put(new org.json.JSONObject().put("bar_timestamp_ms",p.t).put("equity",p.equity));for(Fill f:fillRecords)records.put(new org.json.JSONObject().put("timestamp_ms",f.t).put("side",f.side).put("price",f.price).put("quantity",f.quantity).put("fee",f.fee));org.json.JSONObject j=new org.json.JSONObject().put("mode","MOBILE_PAPER_EMA_SPOT_V2").put("report_schema_version",2).put("full_v1_1_implemented",false).put("closed_trades",sells).put("ending_equity",equity()).put("return_pct",(equity()/start-1)*100).put("max_drawdown_pct",maxDD).put("position_quantity",qty).put("halted",halted).put("fills",new org.json.JSONArray(fills)).put("fill_records",records).put("equity_curve",points).put("win_rate",winRate()==null?org.json.JSONObject.NULL:winRate()).put("profit_factor_net",profitFactor()==null?org.json.JSONObject.NULL:profitFactor()).put("total_fees",totalFees).put("price_currency",priceCurrency).put("curve_time_basis","input_or_observed_bar_timestamp").put("curve_truncated",bars>curve.size()).put("fill_records_truncated",buys+sells>fillRecords.size());return j.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){return new byte[0];}}
 public static final class Live {
  public final long started=System.currentTimeMillis();public final StrategyCore engine;public Bar bar;public boolean running=true;boolean discard=true;long event=Long.MIN_VALUE,received=Long.MIN_VALUE;public String symbol;
  public Live(String symbol,double equity,double fee,double slip){this.symbol=symbol;engine=new StrategyCore(equity,fee,slip);engine.curveLimit=3600;engine.priceCurrency="KRW";}
  public void pause(String why){running=false;engine.reason=why+" · 잔여 모의 보유 유지";engine.pending=0;}
  public void tick(long t,long receive,long now,double price){if(!running)return;if(!MarketMath.valid(price,t,receive,now,15000)){pause("지연 시세로 일시 정지");return;}if(t<event||receive<=received)return;if(received!=Long.MIN_VALUE&&receive-received>15000){pause("수신 공백으로 일시 정지");return;}event=t;received=receive;long bucket=t/60000*60000;if(bar==null){bar=new Bar(bucket,price,price,price,price,0);return;}if(bucket<bar.t)return;if(bucket>bar.t){if(bucket-bar.t!=60000){pause("관측 봉 공백으로 일시 정지");return;}if(!discard)engine.close(bar);discard=false;engine.open(t,price);bar=new Bar(bucket,price,price,price,price,0);}else{bar.h=Math.max(bar.h,price);bar.l=Math.min(bar.l,price);bar.c=price;}engine.observe(t,price);}
 }
}
